const s = $input.first().json;
const ev = (bot, type) => (s[bot].events24h.find((e) => e.type === type) || { n: 0 }).n;
const src = (bot) => s[bot].sources.map((r) => `  ${r.source}: ${r.n}`).join('\n');
const lines = [
  '📊 <b>Воронка</b>',
  '',
  `🧠 <b>Кодекс</b>: ${s.bias.users} польз. (+${s.bias.new24h} за сутки), подписаны ${s.bias.subscribed}, ушли ${s.bias.blocked}`,
  `Карточек за сутки: ${ev('bias', 'today') + ev('bias', 'random') + ev('bias', 'browse') + ev('bias', 'search') + ev('bias', 'deeplink')}, квиз: ${ev('bias', 'quiz_right') + ev('bias', 'quiz_wrong')}, переходов в ЗОЖ: ${ev('bias', 'open_health') + ev('bias', 'promo_health')}`,
  'Источники:', src('bias'),
  '',
  `💪 <b>ЗОЖ</b>: ${s.health.users} польз. (+${s.health.new24h}), с напоминаниями ${s.health.subscribed}`,
  `Отметок привычек за сутки: ${ev('health', 'checkin')}`,
  'Источники:', src('health'),
  '',
  `🎬 Роликов опубликовано: ${s.videos_published}, осталось: ${s.videos_left}`,
];
return [{ json: { text: lines.join('\n') } }];
